SELECT 314, 'case-7-handoff', '案例 3 · handoff：工具写 state，中间件换提示词与工具', 'Custom', NULL, NULL, NULL, '{"model": "deepseek-flash", "temperature": 0.0, "max_tokens": 3000, "reasoning_effort": "low", "modalities": null, "recursion_limit": null, "system_prompt": "你是客服入口，先判断用户的问题类型。", "tools": [], "native_tools": ["web_search", "python_execute"], "cli_tools": [], "custom_tools": [], "tool_params": null, "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [{"type": "handoff", "enabled": true, "config": {"state_field": "handoff_to", "default_step": "sales", "steps": {"sales": {"label": "售前", "description": "产品、报价、方案", "system_prompt": "你是销售助手，只谈产品与报价。技术故障不要自己答，用 transfer_to_support 转给售后。", "tools": ["web_search"], "transfers": [{"to": "support", "description": "技术故障、售后问题交给售后支持"}]}, "support": {"label": "售后", "description": "故障排查、技术问题", "system_prompt": "你是技术支持专家，用 web_search/python_execute 查证后给出排查步骤。发票和账务问题交给财务。", "tools": ["web_search", "python_execute"], "transfers": [{"to": "sales", "description": "用户要问价格或采购，转回售前"}, {"to": "finance", "description": "发票、报销、账务问题转财务"}]}, "finance": {"label": "财务", "description": "发票、报销、账务", "system_prompt": "你是财务专家，负责回答发票、报销、账务问题。", "tools": [], "transfers": [{"to": "support", "description": "技术故障转回售后"}]}}}}], "subagents": [], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000, "keep_last_messages": 20}, "enable_auto_eviction": true, "enable_summarization": true}, "skills": [], "plugins": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false}', '[{"type": "handoff", "enabled": true, "config": {"state_field": "handoff_to", "default_step": "sales", "steps": {"sales": {"label": "售前", "description": "产品、报价、方案", "system_prompt": "你是销售助手，只谈产品与报价。技术故障不要自己答，用 transfer_to_support 转给售后。", "tools": ["web_search"], "transfers": [{"to": "support", "description": "技术故障、售后问题交给售后支持"}]}, "support": {"label": "售后", "description": "故障排查、技术问题", "system_prompt": "你是技术支持专家，用 web_search/python_execute 查证后给出排查步骤。发票和账务问题交给财务。", "tools": ["web_search", "python_execute"], "transfers": [{"to": "sales", "description": "用户要问价格或采购，转回售前"}, {"to": "finance", "description": "发票、报销、账务问题转财务"}]}, "finance": {"label": "财务", "description": "发票、报销、账务", "system_prompt": "你是财务专家，负责回答发票、报销、账务问题。", "tools": [], "transfers": [{"to": "support", "description": "技术故障转回售后"}]}}}}]', '[]', '{"type": "state", "config": {}, "mappings": null}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000, "keep_last_messages": 20}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1.0.0', TRUE, FALSE, '2026-10-31 10:46:58.938636+00:00', '2026-10-31 15:21:48.954274+00:00', 1
