tion_threshold_bytes": 1000000}}, {"type": "subagent", "enabled": true, "config": {"max_depth": 3, "max_concurrent": 5}}]', '[{"name": "database_architect", "description": "Database schema and optimization expert", "type": "dictionary", "template_id": null, "model": "deepseek-flash", "system_prompt": "You design database schemas, optimize queries, and plan data models.", "tools": ["ls", "read_file", "write_file", "edit_file", "glob", "grep", "web_search"], "middleware": ["filesystem"], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}, {"name": "api_designer", "description": "API design and REST/GraphQL expert", "type": "dictionary", "template_id": null, "model": "deepseek-flash", "system_prompt": "You design APIs following best practices, RESTful principles, and modern patterns.", "tools": ["ls", "read_file", "write_file", "edit_file", "glob", "grep", "web_search"], "middleware": ["filesystem"], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}, {"name": "infrastructure_planner", "description": "Cloud infrastructure and DevOps expert", "type": "dictionary", "template_id": null, "model": "deepseek-flash", "system_prompt": "You plan cloud infrastructure, CI/CD pipelines, and deployment strategies.", "tools": ["ls", "read_file", "write_file", "edit_file", "glob", "grep", "web_search"], "middleware": ["filesystem"], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}]', '{"type": "composite", "config": {}, "mappings": {"/memory/": {"type": "vectordb", "config": {}}, "/filesystem/": {"type": "filesystem", "config": {}}, "/state/": {"type": "state", "config": {}}}}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_aut