SELECT 332, 'weather-math-supervisor', 'T2 结构：主 agent 只做分派与汇总（只有 task 工具），天气问题交 weather_expert，算术问题交 math_expert。', 'Custom', NULL, NULL, NULL, '{"model": null, "temperature": 0.0, "max_tokens": null, "reasoning_effort": "low", "modalities": null, "recursion_limit": null, "system_prompt": "你是分派与汇总的总控（supervisor），负责选人 + 汇总。你自己不执行业务动作，也不自己查资料或口算。\n\n## 分派规则\n- 天气、气温、晴雨、某个城市现在天气怎么样 → weather_expert\n- 算术、数值计算、乘除加减、百分比 → math_expert\n- 一句话里有两件事：分别派给两个人（可以按需一次并行派出），再合并成一段回答\n\n## 汇报\n- 每个专家的回报 ≤3 行；细节留在专家那边\n- 合并时按用户问的顺序写，不要按专家顺序\n- 天气要给城市 + 天气状况 + 温度；算术要给算式和结果\n\n## 边界\n- 不属于任何专家：直接说没有这个能力，不要硬凑", "tools": [], "native_tools": ["task"], "cli_tools": [], "custom_tools": [], "tool_params": null, "mcp_servers": null, "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [], "subagents": [{"name": "weather_expert", "description": "什么时候派给我：用户问某个城市现在的天气、气温、晴雨、要不要带伞时，派给我。", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "你是 weather_expert。只做一件事：查指定城市当前的天气。\n用 web_search 检索（必要时 web_fetch 打开结果页取细节）；做完用 ≤3 行回报：城市 + 天气状况 + 温度 + 来源。\n不要解释过程，不要写文件。", "tools": ["web_search", "web_fetch"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}, {"name": "math_expert", "description": "什么时候派给我：用户要做算术或数值计算（加减乘除、乘方、百分比）时，派给我。", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "你是 math_expert。只做一件事：做数值计算。\n可用 reasoning_chain 分步核对算式；做完用 ≤3 行回报：算式 = 结果。\n不要解释过程，不要写文件。", "tools": ["reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}], "backend": {"type": "composite", "config": {}, "mappings": {"/memory/": {"type": "vectordb", "config": {}}, "/filesystem/": {"type": "filesystem", "config": {}}, "/state/": {"type": "state", "config": {}}}}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000, "keep_last_messages": 20}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": [], "plugins": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false}', '[]', '[{"name": "weather_expert", "description": "什么时候派给我：用户问某个城市现在的天气、气温、晴雨、要不要带伞时，派给我。", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "你是 weather_expert。只做一件事：查指定城市当前的天气。\n用 web_search 检索（必要时 web_fetch 打开结果页取细节）；做完用 ≤3 行回报：城市 + 天气状况 + 温度 + 来源。\n不要解释过程，不要写文件。", "tools": ["web_search", "web_fetch"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}, {"name": "math_expert", "description": "什么时候派给我：用户要做算术或数值计算（加减乘除、乘方、百分比）时，派给我。", "type": "dictionary", "template_id": null, "model": null, "system_prompt": "你是 math_expert。只做一件事：做数值计算。\n可用 reasoning_chain 分步核对算式；做完用 ≤3 行回报：算式 = 结果。\n不要解释过程，不要写文件。", "tools": ["reasoning_chain"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null, "graph_id": null, "database": null}]', '{"type": "composite", "config": {}, "mappings": {"/memory/": {"type": "vectordb", "config": {}}, "/filesystem/": {"type": "filesystem", "config": {}}, "/state/": {"type": "state", "config": {}}}}', '{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000, "keep_last_messages": 20}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}', '{}', 0, NULL, '1.0.0', FALSE, FALSE, '2026-11-01 06:29:06.812152+00:00', '2026-11-01 06:29:06.812152+00:00', 1
